package com.nexusai.platform.storage;

import java.io.IOException;
import java.io.InputStream;

/**
 * Storage for original uploaded binaries, kept outside PostgreSQL. The database stores only
 * the returned key. Keys are generated by the storage, never derived from user input.
 */
public interface FileStorage {

    /** Streams {@code content} into new storage and returns its key, size and SHA-256. */
    StoredFile store(String namespace, InputStream content) throws IOException;

    InputStream open(String key) throws IOException;

    /** Deletes the object if present. */
    void delete(String key) throws IOException;

    boolean exists(String key);

    record StoredFile(String key, long sizeBytes, String sha256) {}
}
